def transform(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    # fill zeros by diagonal recurrence: g[r][c]=g[r-1][c+1], iterate
    for _ in range(60):
        changed=False
        for r in range(H):
            for c in range(W):
                if g[r][c]==0:
                    if r>0 and c+1<W and g[r-1][c+1]!=0:
                        g[r][c]=g[r-1][c+1]; changed=True
                    elif r+1<H and c>0 and g[r+1][c-1]!=0:
                        g[r][c]=g[r+1][c-1]; changed=True
        if not changed: break
    return g
